import React, { useState, useEffect } from "react";

export default function LifetimeWithdraw() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetch("http://localhost:8080/api/withdraw/lifetime", {
      method: "GET",
      headers: {
        "Accept": "*/*",
        // যদি token authentication লাগে, uncomment করো নিচের লাইনটি:
        // "Authorization": `Bearer ${localStorage.getItem("authToken")}`
      },
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`HTTP error! status: ${res.status}`);
        }
        return res.json();
      })
      .then((data) => {
        setData(data);
        setLoading(false);
      })
      .catch((err) => {
        setError("Failed to fetch data: " + err.message);
        setLoading(false);
      });
  }, []);

  if (loading) {
    return <div className="p-4 text-center text-gray-600">Loading lifetime withdrawals...</div>;
  }

  if (error) {
    return <div className="p-4 text-center text-red-600">{error}</div>;
  }

  return (
    <div className="max-w-4xl mx-auto p-6 bg-white shadow-md rounded-md">
      <h2 className="text-2xl font-semibold mb-4">Lifetime Withdrawals</h2>
      {/* ডেটার স্ট্রাকচার অনুযায়ী নিচের অংশটা কাস্টমাইজ করো */}
      {data && data.length > 0 ? (
        <table className="w-full border-collapse border border-gray-300">
          <thead>
            <tr className="bg-gray-100">
              <th className="border border-gray-300 px-4 py-2">ID</th>
              <th className="border border-gray-300 px-4 py-2">Amount</th>
              <th className="border border-gray-300 px-4 py-2">Date</th>
              <th className="border border-gray-300 px-4 py-2">Status</th>
              {/* প্রয়োজন অনুযায়ী আরো কলাম যোগ করো */}
            </tr>
          </thead>
          <tbody>
            {data.map((withdraw) => (
              <tr key={withdraw.id} className="text-center">
                <td className="border border-gray-300 px-4 py-2">{withdraw.id}</td>
                <td className="border border-gray-300 px-4 py-2">৳ {withdraw.amount.toFixed(2)}</td>
                <td className="border border-gray-300 px-4 py-2">{new Date(withdraw.date).toLocaleDateString()}</td>
                <td className="border border-gray-300 px-4 py-2">{withdraw.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No lifetime withdrawals found.</p>
      )}
    </div>
  );
}
